                {label && (
                    <Label className={b('item-label')} theme={label.theme}>
                        {label.content}
                    </Label>
                )}
            </div>
            {meta && <div className={b('item-meta')}>{meta}</div>}
        </div>
    );
}

TabsItem.displayName = 'Tabs.Item';
