            | 'disablePortal'
            | 'open'
            | 'onOpenChange'
            | 'strategy'
            | 'placement'
            | 'offset'
            | 'keepMounted'
            | 'hasArrow'
            | 'modal'
            | 'initialFocus'
            | 'returnFocus'
