    const {
        children,
        open,
        onOpenChange,
        toggle = true,
        disabled,
        content,
        trigger = 'all',
        openDelay = DEFAULT_OPEN_DELAY,
        closeDelay = DEFAULT_CLOSE_DELAY,
        rest = DEFAULT_REST,
        enableSafePolygon,
