CAAC","sourcesContent":["import * as React from 'react';

import {useDefaultProps} from '../theme/useDefaultProps';
import {filterDOMProps} from '../utils/filterDOMProps';

import {AvatarIcon} from './AvatarIcon';
import {AvatarImage} from './AvatarImage';
import {AvatarText} from './AvatarText';
import {DEFAULT_AVATAR_SIZE, bAvatar} from './constants';
import type {AvatarProps} from './types/main';

import './Avatar.scss';

export const Avatar = React.forwardRef<HTMLDivElement, AvatarProps>((rawProps, ref) => {
    const props = useDefaultProps('Avatar', rawProps);
    const {
        size = DEFAULT_AVATAR_SIZE,
        theme = 'normal',
        view = 'filled',
        shape = 'circle',
        backgroundColor,
        borderColor,
        title,
        className,
        style: styleProp,
        qa,
    } = props;

    const style = {backgroundColor, color: borderColor, ...styleProp};

    const renderContent = () => {
        if ('imgUrl' in props && props.imgUrl) {
            return (
                <AvatarImage
                    imgUrl={props.imgUrl}
                    fallbackImgUrl={props.fallbackImgUrl}
                    sizes={props.sizes}
                    srcSet={props.srcSet}
                    alt={props.alt || title}
                    loading={props.loading}
                    withImageBorder={props.withImageBorder}
                    size={size}
                />
            );
        }

        if ('icon' in props && props.icon) {
            return <AvatarIcon icon={props.icon} color={props.color} size={size} />;
        }

        if ('text' in props && props.text) {
            return <AvatarText text={props.text} color={props.color} size={size} />;
        }

        return null;
    };

    return (
        <div
            className={bAvatar(
                {size, theme, view, shape, 'with-border': Boolean(borderColor)},
                className,
            )}
            title={title}
            role="img"
            style={style}
            data-qa={qa}
            ref={ref}
            {...filterDOMProps(props, {labelable: true})}
        >
            {renderContent()}
        </div>
    );
});

Avatar.displayName = 'Avatar';
"]}
