type ExtraProps = Omit<
    React.HTMLProps<HTMLDivElement>,
    | 'role'
    | 'aria-selected'
    | 'aria-disabled'
    | 'tabIndex'
    | 'className'
    | 'title'
    | 'onClick'
    | 'onKeyDown'
>;

export interface TabsItemProps extends QAProps {
    id: string;
    className?: string;
    title: string | React.ReactNode;
    meta?: string;
    hint?: string;
    active?: boolean;
    disabled?: boolean;
    hasOverflow?: boolean;
    icon?: React.ReactNode;
    counter?: number | string;
    label?: {
        content: React.ReactNode;
