    meta,
    hint,
    icon,
    counter,
    label,
    active,
    disabled,
    hasOverflow,
    extraProps,
    onClick,
    qa,
}: TabsItemProps) {
    const {activeTabId} = React.useContext(TabsContext);
    const isActive = typeof active === 'boolean' ? active : activeTabId === id;

    const handleClick = () => {
        onClick(id);
